const clean = (value) =>
  String(value ?? '').trim().replace(/\s+/g, ' ');

return {
  json: {
    ...$json,
    full_name: clean($json.full_name),
    email: clean($json.email).toLowerCase(),
    company: clean($json.company),
    service_needed: clean($json.service_needed),
    project_description: clean($json.project_description),
    budget_range: clean($json.budget_range),
    desired_timeline: clean($json.desired_timeline)
  }
};

const lead = $json;

return {
  json: {
    ...lead,
    ai_input: {
      service_needed: lead.service_needed,
      project_description: lead.project_description,
      budget_range: lead.budget_range,
      desired_timeline: lead.desired_timeline
    }
  }
};

const lead = $('CallLeadQualificationAI').first().json;

const plans = {
  high: {
    next_action: 'Schedule discovery call within 1 business day'
  },
  medium: {
    next_action: 'Request more project details within 3 business days'
  },
  low: {
    next_action: 'Send exploratory follow-up within 7 business days'
  }
};

const plan = plans[lead.lead_priority] ?? plans.low;

return {
  json: {
    ...lead,
    next_action: plan.next_action,
    follow_up_status: 'draft_pending_review'
  }
};

const lead = $json;

const messages = {
  high: "Would you be available for a short discovery call to discuss your project?",
  medium: "Could you share more details about your current tools and requirements?",
  low: "Could you tell us more about your project scope and preferred timeline?"
};

const question = messages[lead.lead_priority]
  ?? messages.low;

const subject = `Following up on your ${lead.service_needed} inquiry`;

const body = `Hi ${lead.full_name},

Thank you for contacting us about ${lead.service_needed}.

${question}

We look forward to learning more about your requirements.

Best regards,
Sales Team`;

return {
  json: {
    ...lead,
    follow_up_subject: subject,
    follow_up_body: body
  }
};

const lead = $('PlanSalesFollowUp').first().json;

return {
  json: {
    lead_id: lead.lead_id,
    full_name: lead.full_name,
    email: lead.email,
    company: lead.company,
    service_needed: lead.service_needed,
    project_description: lead.project_description,
    budget_range: lead.budget_range,
    desired_timeline: lead.desired_timeline,
    lead_score: lead.lead_score,
    lead_priority: lead.lead_priority,
    ai_summary: lead.ai_summary
  }
};

const runId = String($execution.id || Date.now());

return {
  json: {
    full_name: "John Smith",
    email: `demo+${runId}@example.com`,
    company: "Demo Tech Solutions",
    service_needed: "AI Automation",
    project_description:
      "We need an AI-powered sales automation system that captures leads, qualifies them, updates our CRM, generates professional quotations, and tracks invoices and payments.",
    budget_range: "Over $2,000",
    desired_timeline: "ASAP",
    demo_mode: true
  }
};

// Manual demo summary. No Form node is needed on this path.
const executed = name => $(name).isExecuted;
const lead = executed('SaveNewLead') ? $('SaveNewLead').first().json : {};
const proposal = executed('CallSalesProposal') ? $('CallSalesProposal').first().json : {};
const pipeline = executed("Call 'P02 | Sales Pipeline & Approvals - Final'")
  ? $("Call 'P02 | Sales Pipeline & Approvals - Final'").first().json : {};
const qualificationFailed = executed('MarkAIQualificationFailed');
const proposalFailed = executed('MarkProposalNeedsReview');
const pipelineFailed = executed('MarkPipelineHandoffFailed');
return {json:{
  status: qualificationFailed ? 'qualification_failed' : pipelineFailed ? 'pipeline_handoff_failed' :
    proposalFailed ? 'proposal_needs_review' : 'demo_completed',
  demo_mode:true,
  lead_id:lead.lead_id ?? null,
  lead_score: executed('CallLeadQualificationAI') ? $('CallLeadQualificationAI').first().json.lead_score ?? null : null,
  quote_id:proposal.quote_id ?? null,
  proposal_saved:proposal.storage?.saved === true,
  opportunity_id:pipeline.opportunity_id ?? null,
  note:'Demo only. Finance approval, contract signature and payment recording are separate human-operated steps.'
}};
